#include "gateway_warehouse_page.h"

const char GATEWAY_WAREHOUSE_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'>"
"<meta name='viewport' content='width=device-width,initial-scale=1'>"
"<meta name='color-scheme' content='dark'><title>AUBOT | Thiết lập kho</title>"
"<link rel='stylesheet' href='/ui.css?v=5'><style>"
".warehouse-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}"
".tile{min-height:140px;padding:15px;border:1px solid var(--line);border-radius:11px;background:var(--glass);color:var(--text);text-align:left}"
".tile .position{display:block;color:#dbeafe;font-size:17px;font-weight:850}.tile .state{display:block;margin-top:17px;font-weight:850}.tile .meta{display:block;margin-top:6px;color:var(--muted);font-size:11px}"
".tile.EMPTY{border-color:rgba(52,211,153,.4)}.tile.OCCUPIED{border-color:rgba(251,191,36,.48)}"
".section{margin-top:14px;padding-top:14px;border-top:1px solid var(--line2)}"
".dialog-tabs{display:flex;gap:6px;margin-bottom:16px;padding:4px;border:1px solid var(--line2);border-radius:10px;background:var(--glass2)}"
".dialog-tabs .btn{flex:1;border:0;color:var(--muted)}.dialog-tabs .btn.active{background:rgba(52,211,153,.14);color:#a7f3d0}.tab-pane.hidden{display:none}"
".auto-laser{min-height:46px;display:flex;align-items:center;padding:9px 11px;border:1px solid var(--line);border-radius:9px;background:var(--glass2);font-weight:750}"
".runtime{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.runtime div{padding:9px;border:1px solid var(--line2);border-radius:8px;background:var(--glass2)}.runtime small{display:block;color:var(--muted)}"
".group-option:disabled{color:#64748b}"
".zone-details{margin-top:14px;padding:0;border:1px solid var(--line);border-radius:11px;background:var(--glass2);overflow:hidden}.zone-details>summary{min-height:48px;display:flex;align-items:center;padding:0 13px;cursor:pointer;font-weight:800;list-style:none}.zone-details>summary::-webkit-details-marker{display:none}.zone-details>summary:after{content:'+';margin-left:auto;color:#7dd3fc;font-size:19px}.zone-details[open]>summary:after{content:'−'}.zone-body{padding:0 13px 13px;border-top:1px solid var(--line2)}.zone-help{margin:11px 0 12px;color:var(--muted);font-size:12px;line-height:1.5}.zone-layout{display:block}.zone-scroll{max-width:100%;overflow-x:auto;padding:2px 2px 7px}.zone-matrix{display:grid;grid-template-columns:44px repeat(8,44px);grid-template-rows:repeat(9,44px);gap:8px;min-width:460px;margin-inline:auto}.zone-axis,.zone-cell,.zone-corner{display:grid;place-items:center;min-height:44px;border-radius:8px;font-size:11px}.zone-axis{border:1px solid var(--line);background:#15243a;color:var(--muted);cursor:pointer;font-weight:800;touch-action:manipulation;transition:background .18s,border-color .18s,color .18s}.zone-axis:hover{background:#203654}.zone-axis:focus-visible{outline:2px solid #7dd3fc;outline-offset:2px}.zone-axis.selected{border-color:#38bdf8;background:#0c4a6e;color:#e0f2fe}.zone-cell{border:1px solid var(--line2);background:#0b1729;color:#64748b}.zone-cell.active{border-color:rgba(52,211,153,.58);background:repeating-linear-gradient(135deg,#123524,#123524 7px,#17452f 7px,#17452f 14px);color:#bbf7d0}.zone-cell.active:after{content:'✓';font-size:15px;font-weight:900}.zone-corner{border:1px dashed var(--line);color:var(--muted);font-weight:800}.zone-meta{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:13px}.zone-stat{padding:10px;border:1px solid var(--line2);border-radius:8px;background:#0b1729}.zone-stat small{display:block;color:var(--muted);font-size:10px}.zone-stat b{display:block;margin-top:3px;color:#dbeafe;font-size:13px}.zone-actions{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:8px}.zone-actions .btn{min-height:42px;padding:0 8px;font-size:11px}.zone-legend{display:flex;align-items:center;gap:8px;margin-top:8px;color:var(--muted);font-size:11px}.zone-swatch{width:16px;height:16px;flex:0 0 16px;border:1px solid rgba(52,211,153,.58);border-radius:4px;background:repeating-linear-gradient(135deg,#123524,#123524 4px,#17452f 4px,#17452f 8px)}@media(max-width:760px){.warehouse-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.zone-matrix{grid-template-columns:40px repeat(8,40px);grid-template-rows:repeat(9,40px);gap:5px;min-width:400px}.zone-axis,.zone-cell,.zone-corner{min-height:40px}.zone-meta{grid-template-columns:1fr}.zone-actions{grid-template-columns:1fr 1fr}}@media(max-width:390px){.warehouse-grid,.runtime{grid-template-columns:1fr}}"
"</style></head><body data-page='factory'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Thiết lập vị trí kho</h1><p>Gán độc lập 12 vị trí kho với nhóm Laser</p></div></div><div data-app-user></div></header>"
"<div data-system-bar></div><nav class='nav' data-app-nav></nav>"
"<section class='toolbar'><b>12 VỊ TRÍ KHO</b><div id='summary'>Đang đọc…</div></section>"
"<main id='grid' class='warehouse-grid'></main></div>"
"<dialog id='dlg'><header class='dialog-head'><div><div class='eyebrow'>THIẾT LẬP KHO</div><h2 id='title'>Vị trí</h2></div><button class='btn ghost' type='button' id='close'>Đóng</button></header>"
"<form id='form' class='dialog-body'><nav class='dialog-tabs' aria-label='Nội dung cấu hình'><button class='btn active' type='button' id='positionTab'>Vị trí kho</button><button class='btn' type='button' id='laserTab'>Cấu hình Laser</button></nav>"
"<div class='tab-pane' id='positionPane'><section><div class='fields'><label class='switch-line full'><span>Sử dụng vị trí kho này</span><input id='enabled' type='checkbox'></label></div></section>"
"<section class='section'><h3>Nhóm Laser</h3><div class='fields'><label class='field full'><span>Nhóm phụ trách vị trí</span><select id='group'></select></label><label class='field full'><span>Dải ID của nhóm</span><input id='range' readonly></label></div></section>"
"<section class='section'><h3>Realtime</h3><div id='runtime' class='runtime'></div></section></div>"
"<div class='tab-pane hidden' id='laserPane'><section><h3>Cấu hình Laser</h3><div class='fields'><div class='field full'><span class='field-label'>Laser được chọn tự động</span><div id='laserAuto' class='auto-laser'>Chưa có Laser online</div><input id='laser' type='hidden' value='0'></div></div></section>"
"<section class='section'><h3>Vùng phát hiện</h3><div class='fields'><label class='field'><span>Khoảng cách (mm)</span><input id='distance' type='number' min='0' max='1200'></label><label class='field'><span>Khẩn cấp (mm)</span><input id='emergency' type='number' min='0' max='1200'></label><label class='switch-line full'><span>Bật Laser phát hiện hàng hóa</span><input id='proximity' type='checkbox'></label></div>"
"<details class='zone-details' open><summary>Vùng quan sát 8×8</summary><div class='zone-body'><p class='zone-help'>Bấm H1–H8 để chọn hàng từ trên xuống dưới; bấm C1–C8 để chọn cột từ phải sang trái. Ô có dấu tích là vùng đang phát hiện.</p><input id='row' type='hidden'><input id='col' type='hidden'><div class='zone-layout'><div><div class='zone-scroll'><div id='zoneGrid' class='zone-matrix' role='grid' aria-label='Ma trận vùng quan sát Laser 8 hàng 8 cột'></div></div><div class='zone-legend'><i class='zone-swatch'></i><span id='zoneCellSummary'>Đang đọc vùng quan sát.</span></div></div><aside class='zone-meta'><div class='zone-stat'><small>Hàng đang bật</small><b id='zoneRows'>--</b></div><div class='zone-stat'><small>Cột đang bật</small><b id='zoneCols'>--</b></div><div class='zone-stat'><small>Vùng phát hiện</small><b id='zoneCells'>--</b></div><div class='zone-actions'><button class='btn ghost' id='zoneAll' type='button'>Bật toàn bộ</button><button class='btn ghost' id='zoneClear' type='button'>Tắt toàn bộ</button></div></aside></div></div></details></section></div>"
"<div id='message' class='message' aria-live='polite'></div><p id='hint' class='hint'>Lưu mapping trước khi áp dụng xuống Laser.</p>"
"<div class='dialog-actions'><button class='btn danger' type='button' id='clear'>Xóa gán nhóm</button><button class='btn secondary' type='button' id='apply' disabled>Áp dụng xuống Laser</button><button class='btn primary' id='save'>Lưu mapping</button></div></form></dialog>"
"<script src='/ui.js?v=5'></script><script>"
"const $=x=>document.getElementById(x),label=s=>s==='EMPTY'?'KHÔNG CÓ HÀNG':s==='OCCUPIED'?'CÓ HÀNG':'CHƯA XÁC ĐỊNH';let snap,groups=[],nodes=[],editing=0,saved='',statusTimer;const nodeById=Array(65);"
"function message(t,c=''){$('message').textContent=t;$('message').className='message '+c}"
"function sig(x){return[x.position_id,x.group_id,x.laser_id,Number(x.config_distance_mm??x.distance_mm),Number(x.config_emergency_mm??x.emergency_mm),Number(x.low_col),Number(x.high_row),Number(x.enabled),Number(x.proximity_enabled??x.proximity)].join('|')}"
"function formData(){return{position_id:editing,group_id:$('group').value,laser_id:$('laser').value,distance_mm:$('distance').value,emergency_mm:$('emergency').value,low_col:$('col').value,high_row:$('row').value,enabled:$('enabled').checked?1:0,proximity:$('proximity').checked?1:0}}"
"function maskValue(id){const value=Math.max(0,Math.min(255,Number($(id).value)||0));$(id).value=value;return value}"
"function renderZoneMatrix(){const rows=maskValue('row'),cols=maskValue('col'),order=[7,6,5,4,3,2,1,0],activeRows=8-Array.from({length:8},(_,i)=>(rows>>i)&1).reduce((a,b)=>a+b,0),activeCols=8-Array.from({length:8},(_,i)=>(cols>>i)&1).reduce((a,b)=>a+b,0);let html='<div class=\"zone-corner\" aria-hidden=\"true\">H/C</div>';order.forEach(c=>{const active=!(cols&(1<<c));html+='<button class=\"zone-axis '+(active?'selected':'')+'\" type=\"button\" data-zone-col=\"'+c+'\" aria-pressed=\"'+active+'\" aria-label=\"Bật hoặc tắt cột '+(c+1)+'\">C'+(c+1)+'</button>'});for(let r=0;r<8;r++){const rowActive=!(rows&(1<<r));html+='<button class=\"zone-axis '+(rowActive?'selected':'')+'\" type=\"button\" data-zone-row=\"'+r+'\" aria-pressed=\"'+rowActive+'\" aria-label=\"Bật hoặc tắt hàng '+(r+1)+'\">H'+(r+1)+'</button>';order.forEach(c=>{const active=rowActive&&!(cols&(1<<c));html+='<span class=\"zone-cell '+(active?'active':'')+'\" role=\"gridcell\" aria-selected=\"'+active+'\" aria-label=\"Hàng '+(r+1)+', cột '+(c+1)+(active?', đang bật':', đang tắt')+'\"></span>'})}$('zoneGrid').innerHTML=html;$('zoneRows').textContent=activeRows+'/8';$('zoneCols').textContent=activeCols+'/8';$('zoneCells').textContent=(activeRows*activeCols)+'/64 ô';$('zoneCellSummary').textContent=activeRows*activeCols?'Dấu tích: ô đang bật phát hiện vật cản.':'Toàn bộ vùng đang tắt.';$('zoneGrid').querySelectorAll('[data-zone-row]').forEach(b=>b.onclick=()=>{$('row').value=rows^(1<<Number(b.dataset.zoneRow));renderZoneMatrix();syncApply()});$('zoneGrid').querySelectorAll('[data-zone-col]').forEach(b=>b.onclick=()=>{$('col').value=cols^(1<<Number(b.dataset.zoneCol));renderZoneMatrix();syncApply()})}"
"function runtime(p){$('runtime').innerHTML=`<div><small>Trạng thái vị trí</small><b>${label(p.state)}</b></div><div><small>Nhóm Laser</small><b>${p.group_id?'NHÓM '+p.group_id:'CHƯA GÁN'}</b></div><div><small>Cảm biến</small><b>${p.sensor_online?'ONLINE':'OFFLINE'}</b></div>`}"
"function render(){const list=snap.positions||[];$('summary').textContent=`12 vị trí · ${snap.configured} đã cấu hình · ${snap.occupied} có hàng`;$('grid').innerHTML=list.map(p=>`<button class='tile ${p.state}' data-position='${p.position_id}'><strong class='position'>VỊ TRÍ ${p.position_id}</strong><span class='state'>${label(p.state)}</span><span class='meta'>${p.group_id?'Nhóm Laser '+p.group_id:'Chưa gán nhóm Laser'}</span></button>`).join('');document.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>openPosition(Number(b.dataset.position)));if($('dlg').open&&editing)runtime(list[editing-1])}"
"async function loadStatus(){clearTimeout(statusTimer);if(document.hidden){statusTimer=setTimeout(loadStatus,10000);return}try{snap=await gw.fetchJson('/api/factory/status');render()}catch(e){}statusTimer=setTimeout(loadStatus,1800)}"
"async function loadLasers(){const d=await gw.fetchJson('/api/factory/lasers');groups=d.groups||[];nodes=d.nodes||[];nodes.forEach(n=>nodeById[n.id]=n)}"
"function groupOptions(current){return'<option value=0>Chưa gán nhóm</option>'+groups.map(g=>{const used=snap.positions.find(p=>p.position_id!==editing&&p.enabled&&p.group_id===g.id),disabled=(g.online<1||used)&&g.id!==current;return`<option class='group-option' value='${g.id}' ${disabled?'disabled':''}>Nhóm ${g.id} · ID ${g.first}–${g.last} · ${g.online} online${used?' · đang ở vị trí '+used.position_id:''}</option>`}).join('')}"
"function syncLaser(){const id=Number($('group').value),g=groups.find(x=>x.id===id);if(!g){$('range').value='Chưa chọn nhóm';$('laser').value=0;$('laserAuto').textContent='Chưa chọn nhóm Laser';return}$('range').value=`ID ${g.first}–${g.last}`;const online=Array.from({length:g.last-g.first+1},(_,i)=>g.first+i).find(id=>nodeById[id]?.alive);$('laser').value=online||0;$('laserAuto').textContent=online?'ID '+online+' · ONLINE':'Nhóm chưa có Laser online'}"
"function showTab(name){const laser=name==='laser';$('positionPane').classList.toggle('hidden',laser);$('laserPane').classList.toggle('hidden',!laser);$('positionTab').classList.toggle('active',!laser);$('laserTab').classList.toggle('active',laser)}"
"function openPosition(id){editing=id;const p=snap.positions[id-1];$('title').textContent='Vị trí '+id;$('enabled').checked=p.enabled;$('group').innerHTML=groupOptions(p.group_id);$('group').value=p.group_id||0;$('distance').value=p.config_distance_mm??600;$('emergency').value=p.config_emergency_mm??300;$('row').value=p.high_row??0;$('col').value=p.low_col??0;$('proximity').checked=p.proximity_enabled;syncLaser();runtime(p);showTab('position');saved=sig(p);message('');renderZoneMatrix();syncApply();$('dlg').showModal()}"
"function syncApply(){const p=snap.positions[editing-1],same=sig(formData())===saved,ready=p.enabled&&p.group_id&&p.laser_id&&same;$('apply').disabled=!ready;$('hint').textContent=ready?(p.config_applied?'Cấu hình đã áp dụng và sẽ tự khôi phục sau mất điện.':'Mapping đã lưu nhưng chưa áp dụng lần đầu xuống Laser.'):same?'Vị trí phải được bật và gán nhóm Laser online.':'Hãy lưu mapping trước khi áp dụng xuống Laser.'}"
"function errorVi(e){return{DUPLICATE_LASER_GROUP:'Nhóm Laser đã được gán cho vị trí khác.',LASER_GROUP_OFFLINE:'Nhóm này chưa có Laser nào online.',LASER_OUT_OF_GROUP:'Laser tham chiếu không thuộc nhóm đã chọn.',DUPLICATE_LASER_ID:'Laser này đã được sử dụng.',INVALID_DISTANCE:'Khoảng cách không hợp lệ.',INVALID_GROUP:'Vị trí hoặc nhóm không hợp lệ.'}[e]||e}"
"async function save(data){const r=await fetch('/api/factory/warehouse',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)});if(!r.ok)throw Error(await r.text());snap=await gw.fetchJson('/api/factory/status');render();saved=sig(snap.positions[editing-1]);syncApply()}"
"$('positionTab').onclick=()=>showTab('position');$('laserTab').onclick=()=>showTab('laser');$('group').onchange=()=>{syncLaser();message('');syncApply()};$('form').oninput=syncApply;"
"$('zoneAll').onclick=()=>{$('row').value=0;$('col').value=0;renderZoneMatrix();syncApply()};$('zoneClear').onclick=()=>{$('row').value=255;$('col').value=255;renderZoneMatrix();syncApply()};"
"$('form').onsubmit=async e=>{e.preventDefault();const b=$('save');b.disabled=true;message('Đang lưu…');try{await save(formData());message(snap.positions[editing-1].config_applied?'Đã lưu. Cấu hình sẽ tự khôi phục sau mất điện.':'Đã lưu mapping. Cần áp dụng lần đầu xuống Laser.','ok')}catch(x){message(errorVi(x.message),'bad')}finally{b.disabled=false}};"
"$('clear').onclick=async()=>{if(!await gw.confirm('Xóa gán nhóm khỏi vị trí này?',{title:'Xác nhận xóa gán',confirmText:'Xóa gán',danger:true}))return;const p=formData();p.enabled=0;p.group_id=0;p.laser_id=0;try{await save(p);$('dlg').close()}catch(x){message(errorVi(x.message),'bad')}};"
"$('apply').onclick=async()=>{if($('apply').disabled)return;try{const r=await fetch('/api/factory/laser/apply',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({position_id:editing})});if(!r.ok)throw Error(await r.text());snap=await gw.fetchJson('/api/factory/status');render();saved=sig(snap.positions[editing-1]);syncApply();message('Đã áp dụng xuống Laser và ghi nhớ sau mất điện.','ok')}catch(x){message(errorVi(x.message),'bad')}};"
"$('close').onclick=()=>$('dlg').close();document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadStatus()});Promise.all([loadLasers(),gw.fetchJson('/api/factory/status').then(x=>snap=x)]).then(()=>{render();loadStatus()});"
"</script></body></html>";
